struct CTCMapwho {
    int calls;
    void Shutdown();
};

static CTCMapwho* g_last_freed = 0;
static int g_shutdown_count = 0;

void CTCMapwho::Shutdown() { this->calls++; g_shutdown_count++; }

void FreeThing(CTCMapwho* p) { g_last_freed = p; }

void __stdcall OnDie(CTCMapwho* p)
{
    if (p) {
        p->Shutdown();
        FreeThing(p);
    }
}

